// Phase 2: route a classified inbox row to its target table.
// The inbox_id gate runs first, as it always did; the read and the two writes
// that follow are HTTP Request nodes on the stored Supabase credential (moved
// out of "Route + persist" on 2026-10-03, with the service-role key).
const input = $input.first().json;
const body = input.body || input;
const inbox_id = body.inbox_id;
if (!inbox_id) throw new Error('inbox_id required');
return [{ json: { inbox_id } }];

// Works out where the inbox row goes. "Insert target row" makes the insert.
const inbox_id = $('Check inbox id').first().json.inbox_id;
const fetched = $input.first().json.body;
const row = (Array.isArray(fetched) ? fetched : [])[0];
if (!row) throw new Error('inbox row not found');
const cls = row.classification || {};
const rawText = row.raw_text || '';
const firstAction = cls.first_action || rawText.slice(0, 200);
const agent = cls.primary_agent || 'agatha';
const targetTable = cls.target_table || 'tasks';

// The slug fallback is gone. It called compute_concept_slug with p_text, but
// the function takes p_name, so PostgREST never found it and every call
// returned null. Dropping it changes nothing.
const concept_id = cls.suggested_concept_id || null;

function headTitle(t) { return (t || '').replace(/\s+/g, ' ').trim().slice(0, 80); }

let table = targetTable;
let target_table = targetTable;
let routed_to_agent = agent;
let insert;

if (targetTable === 'leads') {
  insert = {
    full_name: headTitle(rawText), status: 'new', assignee_agent: agent,
    why_relevant: firstAction, source: 'inbox',
  };
} else if (targetTable === 'visibility_targets') {
  insert = {
    title: headTitle(firstAction), status: 'queued', type: 'speaking',
    why_relevant: firstAction,
  };
  routed_to_agent = 'nova';
} else if (targetTable === 'guests') {
  insert = { name: headTitle(rawText), status: 'scouted', one_liner: firstAction };
  routed_to_agent = 'nell';
} else if (targetTable === 'content_ideas') {
  insert = {
    idea: headTitle(firstAction), source_snippet: rawText, source_url: null,
    state: 'seeded', source_type: 'inspiration_sweep',
  };
  routed_to_agent = 'cleo';
} else if (targetTable === 'bets') {
  insert = { title: headTitle(firstAction), hypothesis: rawText, status: 'live', kind: 'general' };
  routed_to_agent = 'marcus';
} else if (targetTable === 'customers') {
  // No direct customer create. Create a task linked back via raw_text.
  table = 'tasks';
  target_table = 'tasks';
  insert = {
    title: 'Customer follow-up: ' + headTitle(firstAction), agent, status: 'waiting',
    workstream: 'customer_acquisition', description: rawText, krish_reviewed: false,
  };
} else {
  // tasks (and the unknown-bucket fallthrough)
  table = 'tasks';
  target_table = 'tasks';
  insert = {
    title: headTitle(firstAction), agent, status: 'waiting',
    workstream: cls.task_type === 'content_idea' ? 'content' : 'general',
    description: rawText, krish_reviewed: false,
  };
}

return [{ json: { inbox_id, table, insert, target_table, routed_to_agent, concept_id, first_action: firstAction } }];

// Reads the insert's answer and builds the inbox row's next state. "Save
// route" writes it over the stored Supabase credential (moved out of this
// node's source on 2026-10-03, with the service-role key).
const plan = $('Plan route').first().json;
const res = $input.first().json;
function headTitle(t) { return (t || '').replace(/\s+/g, ' ').trim().slice(0, 80); }

let target_id = null;
let failure = null;
if (res.statusCode >= 200 && res.statusCode < 300) {
  const ins = res.body;
  target_id = (ins && ins[0] && ins[0].id) || null;
} else {
  const b = res.body || {};
  failure = (`HTTP ${res.statusCode}: ` + (b.message || JSON.stringify(b))).slice(0, 250);
}

const patch = failure ? {
  status: 'failed', archive_reason: 'classifier_failed', archived_at: new Date().toISOString(),
} : {
  status: 'in_flight', target_table: plan.target_table, target_id,
  routed_to_agent: plan.routed_to_agent, concept_id: plan.concept_id,
};

const telegram_text = failure
  ? `Inbox router failed: ${failure}`
  : `Inbox routed to ${plan.routed_to_agent}. "${headTitle(plan.first_action)}". Will return when it needs you.`;

return [{ json: {
  ok: !failure, inbox_id: plan.inbox_id, target_table: plan.target_table, target_id,
  routed_to_agent: plan.routed_to_agent, telegram_text, patch,
} }];

// What the webhook answers with, as before. "Save route" has saved the row.
const { patch, ...result } = $('Route + persist').first().json;
return [{ json: result }];
